    "workflowJson": "{\n  \"name\": \"47 Telegram, OpenAI, Google Sheets\",\n  \"nodes\": [\n    {\n      \"parameters\": {\n        \"modelId\": {\n          \"__rl\": true,\n          \"value\": \"models/gemini-2.5-flash\",\n          \"mode\": \"list\",\n          \"cachedResultName\": \"models/gemini-2.5-flash\"\n        },\n        \"messages\": {\n          \"values\": [\n            {}\n          ]\n        },\n        \"options\": {\n          \"systemMessage\": \"=You are a helpful assistant. A Telegram user requested information about an employee. The following is the data from our Google Sheet:\\\\n\\\\n{{ $json.message.text }}\\\\n\\\\nPlease generate a short, polite, and professional summary about this person. Include Name, Role, Department, and notable details from the Notes or Performance columns. Make it suitable to send directly to a Telegram user.\"\n        }\n      },\n      \"type\": \"@n8n/n8n-nodes-langchain.googleGemini\",\n      \"typeVersion\": 1,\n      \"position\": [\n        -144,\n        -96\n      ],\n      \"id\": \"b031ddf7-484a-4dd7-a951-c3f0a3ddba49\",\n      \"name\": \"Message a model\",\n      \"credentials\": {\n        \"googlePalmApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"googlePalmApi\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"updates\": [\n          \"message\"\n        ],\n        \"additionalFields\": {}\n      },\n      \"type\": \"n8n-nodes-base.telegramTrigger\",\n      \"typeVersion\": 1.2,\n      \"position\": [\n        -672,\n        -96\n      ],\n      \"id\": \"604daa76-f03c-4fb1-bfca-f9c0f218767d\",\n      \"name\": \"Telegram Trigger\",\n      \"webhookId\": \"1f3cd552-41fd-44ca-a9d9-514be5025b80\",\n      \"credentials\": {\n        \"telegramApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"telegramApi\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"chatId\": \"={{ $('Telegram Trigger').item.json.message.chat.id }}\",\n        \"text\": \"={{ $json.content.parts[0].text }}\",\n        \"additionalFields\": {}\n      },\n      \"type\": \"n8n-nodes-base.telegram\",\n      \"typeVersion\": 1.2,\n      \"position\": [\n        272,\n        -96\n      ],\n      \"id\": \"d846a9eb-d413-44c0-8154-4e02b2504c28\",\n      \"name\": \"Send a text message\",\n      \"webhookId\": \"0f538733-f35e-491b-a6da-906b726e4227\",\n      \"credentials\": {\n        \"telegramApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"telegramApi\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"conditions\": {\n          \"options\": {\n            \"caseSensitive\": true,\n            \"leftValue\": \"\",\n            \"typeValidation\": \"strict\",\n            \"version\": 2\n          },\n          \"conditions\": [\n            {\n              \"id\": \"230bd4c6-9ae2-4a9d-8761-c30864c7c279\",\n              \"leftValue\": \"={{ $json.message.text }}\",\n              \"rightValue\": \"/lookup\",\n              \"operator\": {\n                \"type\": \"string\",\n                \"operation\": \"contains\"\n              }\n            }\n          ],\n          \"combinator\": \"and\"\n        },\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.if\",\n      \"typeVersion\": 2.2,\n      \"position\": [\n        -496,\n        -96\n      ],\n      \"id\": \"a4ab7454-06a0-4e53-a02c-a1f37ba714d2\",\n      \"name\": \"If\"\n    },\n    {\n      \"parameters\": {\n        \"documentId\": {\n          \"__rl\": true,\n          \"value\": \"{{GOOGLE_DOC_ID}}\",\n          \"mode\": \"list\",\n          \"cachedResultName\": \"sample data\",\n          \"cachedResultUrl\": \"https://docs.google.com/spreadsheets/d/{{DOC_ID}}/edit?usp=drivesdk\"\n        },\n        \"sheetName\": {\n          \"__rl\": true,\n          \"value\": 1468320592,\n          \"mode\": \"list\",\n          \"cachedResultName\": \"lookup employee\",\n          \"cachedResultUrl\": \"https://docs.google.com/spreadsheets/d/{{DOC_ID}}/edit#gid=1468320592\"\n        },\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.googleSheetsTool\",\n      \"typeVersion\": 4.7,\n      \"position\": [\n        0,\n        112\n      ],\n      \"id\": \"6734ce3a-a9b5-4a22-8969-56cd15c74319\",\n      \"name\": \"Get row(s) in sheet in Google Sheets\",\n      \"credentials\": {\n        \"googleSheetsOAuth2Api\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"googleSheetsOAuth2Api\"\n        }\n      }\n    }\n  ],\n  \"connections\": {\n    \"Message a model\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Send a text message\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Telegram Trigger\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"If\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"If\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Message a model\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Get row(s) in sheet in Google Sheets\": {\n      \"ai_tool\": [\n        [\n          {\n            \"node\": \"Message a model\",\n            \"type\": \"ai_tool\",\n            \"index\": 0\n          }\n        ]\n      ]\n    }\n  },\n  \"active\": false,\n  \"settings\": {\n    \"executionOrder\": \"v1\"\n  },\n  \"versionId\": \"5ece271f-5af4-4965-9bdd-9d3e6bdd90c7\",\n  \"meta\": {\n    \"templateCredsSetupCompleted\": true\n  },\n  \"id\": \"DZqvAEyvxAHMiXEM\",\n  \"tags\": [],\n  \"pinData\": {}\n}",
