    "workflowJson": "{\n  \"updatedAt\": \"2025-10-27T06:04:11.000Z\",\n  \"createdAt\": \"2025-10-06T07:57:59.732Z\",\n  \"id\": \"ZC67L3XLlmHRsZU4\",\n  \"name\": \"17 MySQL & Slack Inventorycheck\",\n  \"description\": null,\n  \"active\": false,\n  \"isArchived\": false,\n  \"nodes\": [\n    {\n      \"parameters\": {},\n      \"type\": \"n8n-nodes-base.manualTrigger\",\n      \"typeVersion\": 1,\n      \"position\": [\n        176,\n        -112\n      ],\n      \"id\": \"e75ac06e-6f9c-4242-9315-f350ef0b2a9a\",\n      \"name\": \"When clicking ‘Execute workflow’\"\n    },\n    {\n      \"parameters\": {\n        \"operation\": \"executeQuery\",\n        \"query\": \"SELECT * FROM inventory WHERE quantity < 10;\\n\",\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.mySql\",\n      \"typeVersion\": 2.5,\n      \"position\": [\n        384,\n        -112\n      ],\n      \"id\": \"ba657066-f2f7-4b6a-adbb-22f96095e9b8\",\n      \"name\": \"Execute a SQL query\",\n      \"credentials\": {\n        \"mySql\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"mySql\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"conditions\": {\n          \"options\": {\n            \"caseSensitive\": true,\n            \"leftValue\": \"\",\n            \"typeValidation\": \"strict\",\n            \"version\": 2\n          },\n          \"conditions\": [\n            {\n              \"id\": \"55323a4d-5898-4501-b6c3-f62e57152f44\",\n              \"leftValue\": false,\n              \"rightValue\": \"\",\n              \"operator\": {\n                \"type\": \"boolean\",\n                \"operation\": \"notEmpty\",\n                \"singleValue\": true\n              }\n            }\n          ],\n          \"combinator\": \"and\"\n        },\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.if\",\n      \"typeVersion\": 2.2,\n      \"position\": [\n        592,\n        -112\n      ],\n      \"id\": \"0d4dfb06-ab31-402b-b86b-2dfdab6e1e3f\",\n      \"name\": \"If\"\n    },\n    {\n      \"parameters\": {\n        \"select\": \"channel\",\n        \"channelId\": {\n          \"__rl\": true,\n          \"value\": \"C09FLFGAVFE\",\n          \"mode\": \"list\",\n          \"cachedResultName\": \"customer-support-n8n\"\n        },\n        \"text\": \"=⚠️ Low Inventory Alert!\\n\\n{{ $json.item_name }} — Quantity: {{ $json.quantity }} (Last updated: {{ $json.updated_at }})\\n\",\n        \"otherOptions\": {}\n      },\n      \"type\": \"n8n-nodes-base.slack\",\n      \"typeVersion\": 2.3,\n      \"position\": [\n        896,\n        -128\n      ],\n      \"id\": \"562b48d6-c958-4f68-ab70-1872d61ead14\",\n      \"name\": \"Send a message\",\n      \"webhookId\": \"119e94c3-c8ab-484e-b5e7-68280df79524\",\n      \"credentials\": {\n        \"slackApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"slackApi\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"content\": \"This workflow automatically monitors your MySQL database for low inventory items. It starts with a trigger (manual or scheduled), then runs a SQL query to find items with quantity below a set threshold. An IF node checks if any results were returned, and if so, a Slack or Telegram node sends an alert message with the item details. This ensures you’re notified immediately whenever stock is running low.\",\n        \"height\": 240,\n        \"width\": 304\n      },\n      \"type\": \"n8n-nodes-base.stickyNote\",\n      \"position\": [\n        -16,\n        -448\n      ],\n      \"typeVersion\": 1,\n      \"id\": \"1659e583-9c73-4f4c-ae93-255e52f4e501\",\n      \"name\": \"Sticky Note\"\n    }\n  ],\n  \"connections\": {\n    \"When clicking ‘Execute workflow’\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Execute a SQL query\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Execute a SQL query\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"If\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"If\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Send a message\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    }\n  },\n  \"settings\": {\n    \"executionOrder\": \"v1\"\n  },\n  \"meta\": {\n    \"templateCredsSetupCompleted\": true\n  },\n  \"versionId\": \"ec1188f3-bba0-408a-9973-b0b2ae32ee21\",\n  \"activeVersionId\": null,\n  \"versionCounter\": 1,\n  \"triggerCount\": 0,\n  \"tags\": [],\n  \"shared\": [\n    {\n      \"updatedAt\": \"2025-10-06T07:57:59.741Z\",\n      \"createdAt\": \"2025-10-06T07:57:59.741Z\",\n      \"role\": \"workflow:owner\",\n      \"workflowId\": \"ZC67L3XLlmHRsZU4\",\n      \"projectId\": \"48UocHYHLLjdTB5P\",\n      \"project\": {\n        \"updatedAt\": \"2026-02-02T05:23:54.501Z\",\n        \"createdAt\": \"2025-10-06T05:26:02.944Z\",\n        \"id\": \"48UocHYHLLjdTB5P\",\n        \"name\": \"Muhammad Usama <client@example.com>\",\n        \"type\": \"personal\",\n        \"icon\": null,\n        \"description\": null,\n        \"creatorId\": \"57651b21-6506-4678-85a4-a61e9e0d101c\"\n      }\n    }\n  ],\n  \"pinData\": {}\n}",
