    "workflowJson": "{\n  \"updatedAt\": \"2025-12-11T07:16:59.464Z\",\n  \"createdAt\": \"2025-12-11T07:16:59.464Z\",\n  \"id\": \"ZmSDs3TBJBHE0dPM\",\n  \"name\": \"Overdue Jira Ticket Reminder\",\n  \"description\": null,\n  \"active\": false,\n  \"isArchived\": false,\n  \"nodes\": [\n    {\n      \"parameters\": {},\n      \"id\": \"918adbed-1585-464e-8f31-3154cfd28655\",\n      \"name\": \"Schedule Daily\",\n      \"type\": \"n8n-nodes-base.cron\",\n      \"typeVersion\": 1,\n      \"position\": [\n        -368,\n        -48\n      ]\n    },\n    {\n      \"parameters\": {},\n      \"id\": \"bfa73987-8f05-4e78-a3b7-baf0566431c1\",\n      \"name\": \"Get Jira Tickets\",\n      \"type\": \"n8n-nodes-base.jira\",\n      \"typeVersion\": 2,\n      \"position\": [\n        -112,\n        -48\n      ],\n      \"credentials\": {}\n    },\n    {\n      \"parameters\": {\n        \"conditions\": {\n          \"date\": [\n            {\n              \"value1\": \"={{ $json.fields.duedate }}\",\n              \"operation\": \"earlier\"\n            }\n          ]\n        },\n        \"options\": {}\n      },\n      \"id\": \"f66332f3-1748-44e3-8e81-264d8e25e8bf\",\n      \"name\": \"Check Overdue\",\n      \"type\": \"n8n-nodes-base.if\",\n      \"typeVersion\": 2,\n      \"position\": [\n        144,\n        -48\n      ]\n    },\n    {\n      \"parameters\": {\n        \"subject\": \"Reminder: Jira Ticket Overdue ({{ $json.key }})\",\n        \"message\": \"Hi {{ $json.fields.assignee.displayName }},\\n\\nYour Jira ticket **{{ $json.key }} - {{ $json.fields.summary }}** is overdue.\\nDue Date: {{ $json.fields.duedate }}\\n\\nPlease review and update as needed.\\n\\n— Automated Reminder\",\n        \"options\": {}\n      },\n      \"id\": \"ace6191d-f45d-4beb-9762-a6d0beed9b21\",\n      \"name\": \"Send Gmail Reminder\",\n      \"type\": \"n8n-nodes-base.gmail\",\n      \"typeVersion\": 2,\n      \"position\": [\n        384,\n        -48\n      ],\n      \"webhookId\": \"6444901f-a6d4-4d60-b07b-6ac41c56d618\"\n    },\n    {\n      \"parameters\": {\n        \"operation\": \"getAll\",\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.jira\",\n      \"typeVersion\": 1,\n      \"position\": [\n        -48,\n        64\n      ],\n      \"id\": \"d60ce2e5-7db0-4834-9707-702ec2f5d559\",\n      \"name\": \"Get many issues\",\n      \"credentials\": {\n        \"jiraSoftwareCloudApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"jiraSoftwareCloudApi\"\n        }\n      }\n    }\n  ],\n  \"connections\": {\n    \"Check Overdue\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Send Gmail Reminder\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    }\n  },\n  \"settings\": {\n    \"executionOrder\": \"v1\"\n  },\n  \"meta\": null,\n  \"versionId\": \"7f72ccbb-8085-4e9f-a874-07c7e5ad54bc\",\n  \"activeVersionId\": null,\n  \"versionCounter\": 1,\n  \"triggerCount\": 0,\n  \"tags\": [],\n  \"shared\": [\n    {\n      \"updatedAt\": \"2025-12-11T07:16:59.526Z\",\n      \"createdAt\": \"2025-12-11T07:16:59.526Z\",\n      \"role\": \"workflow:owner\",\n      \"workflowId\": \"ZmSDs3TBJBHE0dPM\",\n      \"projectId\": \"48UocHYHLLjdTB5P\",\n      \"project\": {\n        \"updatedAt\": \"2026-02-02T05:23:54.501Z\",\n        \"createdAt\": \"2025-10-06T05:26:02.944Z\",\n        \"id\": \"48UocHYHLLjdTB5P\",\n        \"name\": \"Muhammad Usama <client@example.com>\",\n        \"type\": \"personal\",\n        \"icon\": null,\n        \"description\": null,\n        \"creatorId\": \"57651b21-6506-4678-85a4-a61e9e0d101c\"\n      }\n    }\n  ],\n  \"pinData\": {}\n}",
