    "workflowJson": "{\n  \"name\": \"11. Google Sheets, Notion\",\n  \"nodes\": [\n    {\n      \"parameters\": {},\n      \"type\": \"n8n-nodes-base.manualTrigger\",\n      \"typeVersion\": 1,\n      \"position\": [\n        -288,\n        -16\n      ],\n      \"id\": \"0b9dce47-6f1b-4943-ba79-84ed9800575d\",\n      \"name\": \"When clicking ‘Execute workflow’\"\n    },\n    {\n      \"parameters\": {\n        \"jsCode\": \"const results = [];\\n\\n$input.all().forEach((item) => {\\n  const row = item.json;\\n\\n  let phone = row[\\\"Phone\\\"] || \\\"\\\";\\n  phone = String(phone).replace(/\\\\D/g, \\\"\\\");  \\n\\n  results.push({\\n    json: {\\n      Name: row[\\\"Name\\\"] || \\\"\\\",\\n      Email: row[\\\"Email\\\"] || \\\"\\\",\\n      \\n    }\\n  });\\n});\\n\\nreturn results;\\n\"\n      },\n      \"type\": \"n8n-nodes-base.code\",\n      \"typeVersion\": 2,\n      \"position\": [\n        128,\n        -16\n      ],\n      \"id\": \"b350dee5-bb03-4cdc-acfc-bdd4d4672341\",\n      \"name\": \"Clean / Transform Rows\"\n    },\n    {\n      \"parameters\": {\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.splitInBatches\",\n      \"typeVersion\": 3,\n      \"position\": [\n        336,\n        -16\n      ],\n      \"id\": \"3ce3f892-24d5-43ca-b0c7-0a868cd3f575\",\n      \"name\": \"Loop Over Items\"\n    },\n    {\n      \"parameters\": {\n        \"documentId\": {\n          \"__rl\": true,\n          \"value\": \"{{GOOGLE_DOC_ID}}\",\n          \"mode\": \"list\",\n          \"cachedResultName\": \"sample data\",\n          \"cachedResultUrl\": \"https://docs.google.com/spreadsheets/d/{{DOC_ID}}/edit?usp=drivesdk\"\n        },\n        \"sheetName\": {\n          \"__rl\": true,\n          \"value\": 1275773505,\n          \"mode\": \"list\",\n          \"cachedResultName\": \"Staff List\",\n          \"cachedResultUrl\": \"https://docs.google.com/spreadsheets/d/{{DOC_ID}}/edit#gid=1275773505\"\n        },\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.googleSheets\",\n      \"typeVersion\": 4.7,\n      \"position\": [\n        -96,\n        -16\n      ],\n      \"id\": \"1a70a506-5d42-4a35-bf8b-77889f1ba541\",\n      \"name\": \"Get row(s) in sheet\",\n      \"credentials\": {\n        \"googleSheetsOAuth2Api\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"googleSheetsOAuth2Api\"\n        }\n      }\n    },\n    {\n      \"parameters\": {\n        \"resource\": \"databasePage\",\n        \"databaseId\": {\n          \"__rl\": true,\n          \"value\": \"2a923383-6835-802f-90c6-f7de305dc9b5\",\n          \"mode\": \"list\",\n          \"cachedResultName\": \"Tasks Tracker\",\n          \"cachedResultUrl\": \"https://www.notion.so/2a9233836835802f90c6f7de305dc9b5\"\n        },\n        \"title\": \"Create Pages in Notion\",\n        \"propertiesUi\": {\n          \"propertyValues\": [\n            {\n              \"key\": \"Names|title\",\n              \"title\": \"={{ $json.Name }}\"\n            },\n            {\n              \"key\": \"Email|email\",\n              \"emailValue\": \"={{ $json.Email }}\"\n            }\n          ]\n        },\n        \"options\": {}\n      },\n      \"type\": \"n8n-nodes-base.notion\",\n      \"typeVersion\": 2.2,\n      \"position\": [\n        656,\n        0\n      ],\n      \"id\": \"956ace2c-33ae-44eb-b58b-0b87bfcfca4c\",\n      \"name\": \"Create a database page1\",\n      \"credentials\": {\n        \"notionApi\": {\n          \"id\": \"REDACTED\",\n          \"name\": \"notionApi\"\n        }\n      }\n    }\n  ],\n  \"connections\": {\n    \"When clicking ‘Execute workflow’\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Get row(s) in sheet\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Clean / Transform Rows\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Loop Over Items\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Loop Over Items\": {\n      \"main\": [\n        [],\n        [\n          {\n            \"node\": \"Create a database page1\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Get row(s) in sheet\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Clean / Transform Rows\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    },\n    \"Create a database page1\": {\n      \"main\": [\n        [\n          {\n            \"node\": \"Loop Over Items\",\n            \"type\": \"main\",\n            \"index\": 0\n          }\n        ]\n      ]\n    }\n  },\n  \"active\": false,\n  \"settings\": {\n    \"executionOrder\": \"v1\"\n  },\n  \"versionId\": \"251325a1-a3c0-4143-8a94-bed87ad6a31c\",\n  \"meta\": {\n    \"templateCredsSetupCompleted\": true\n  },\n  \"id\": \"GnsHRpBwmqhymAgj\",\n  \"tags\": [],\n  \"pinData\": {}\n}",
